class CBase {
	str: string

	constructor(str1: string = '') {

		this.str = str1;

		assert(!this.str.includes('\n'), 'CBase cannot include newline')
	}

	// ..........................................................

	buildStr(maxWidth: number = 78): string {

		return this.str
	}
}

