export const needsEscape = (str: string): boolean => {

	return toBool((
		   setCharNeedsEsc.has(str[0])
		|| str.match(/^[-.]?\d/)        // looks like a number
		|| str.match(/^[^˳\s]+\:\:?˳/)  // looks like a label
		|| str.match(/^--?˳/)           // looks like list item
		))
}

